export type SpaceStep = keyof typeof space;
export type RadiusStep = keyof typeof radius;

/** A token as a CSS custom property, for inline styles: `cssVar("color", "ink")`. */
export function cssVar(
  group: "color" | "space" | "radius" | "shadow" | "font" | "size" | "z" | "duration" | "ease",
  name: string,
): string {
  return `var(--ds-${group}-${name})`;
}
